export const sourceCandidate = (path, data) => SOURCE.test(path) || README.test(path) ||
  (data.subarray(0, 128).toString('utf8').startsWith('#!') && /(?:node|sh|python|ruby|perl|pwsh)/i.test(data.subarray(0, 128).toString('utf8')));
